    OriginalCircuitExperienceErrorV1, OriginalCircuitExperienceReceiptV1,
    OriginalCircuitExperienceRequestV1};
use super::{Error, OriginalCircuitPrefreezeSourceRequestV1, now};

/// Non-Clone client for one explicitly authorized, fixed original Source. It
/// exposes observations and the original intake, never a generic reader or
/// writer. The eventual Material transition consumes this exact client.
pub struct OriginalCircuitPrefreezeSourceV1 {
    source: CircuitTaskSourceReadbackV1<FileAnchorWitnessStore>,
    request: Arc<OriginalCircuitPrefreezeSourceRequestV1>,
    evidence: SignedLearningEvidenceV1,
    identity: AgentdIdentity,
    ledger: Arc<Mutex<LedgerWriter>>,
}

impl OriginalCircuitPrefreezeSourceV1 {
    /// Consume the real stream/pidfd and retain the already-open original
    /// ledger. Root separately requires its opaque protected registration.
    /// Neither these data nor the Generator signature can register that reader.
    pub fn from_original_stream(
        request: OriginalCircuitPrefreezeSourceRequestV1, evidence: SignedLearningEvidenceV1,
        identity: AgentdIdentity, ledger: Arc<Mutex<LedgerWriter>>,
        stream: UnixStream, root: AgentdRootAuthorityPeer, original_root_pidfd: OwnedFd,
        timeout: Duration, lifetime: Duration,
    ) -> Result<Self, Error> {
        let verifier = {
            let original = ledger.try_lock().map_err(|_| Error::Unavailable)?;
            request.require_ledger(&original, &evidence, now()?)?;
            original.verifier().clone()
        };
        let request = Arc::new(request);
        let source = CircuitTaskSourceReadbackV1::from_original_prefreeze_root_stream(
            stream, root, original_root_pidfd, Arc::clone(&request), evidence.clone(), verifier,
            identity.clone(), timeout, lifetime,
        )?;
        {
            let original = ledger.try_lock().map_err(|_| Error::Unavailable)?;
            request.require_ledger(&original, &evidence, now()?)?;
        }
        source.require_original_prefreeze_current()?;
        Ok(Self { source, request, evidence, identity, ledger })
    }

    /// First authorized observation; no Decision or freeze is needed. The full
    /// original RunStart, saved input and result come from Root's actual owner.
    pub fn read_original_publication(&self) -> Result<CircuitTaskSourcePublicationV1, Error> {
        let ledger = self.ledger.try_lock().map_err(|_| Error::Unavailable)?;
        self.request.require_ledger(&ledger, &self.evidence, now()?)?;
        let observed = CircuitTaskSourceReadbackV1::read_run_publication(
            &self.source, &self.identity, &self.request.source.scope.run_id,
        )?;
        self.request.require_ledger(&ledger, &self.evidence, now()?)?;
        self.source.require_original_prefreeze_current()?;
        Ok(observed)
    }

    /// Delegate unchanged to the original signed Generator/independent Observer
    /// intake. Its source checks and two actual appends retain their original
    /// partial-commit behavior. No new signer, outcome or retry is synthesized.
    pub fn append_original_experience_v2(&mut self, request: &OriginalCircuitExperienceRequestV1)
        -> Result<OriginalCircuitExperienceReceiptV1, OriginalCircuitExperienceErrorV1>
    {
        let mut ledger = self.ledger.try_lock().map_err(|_| Error::Unavailable)?;
        self.request.require_ledger(&ledger, &self.evidence, now()?)?;
        let receipt = crate::append_original_circuit_experience_v2(
            &self.source, &self.identity, &mut ledger, request,
        )?;
        self.request.require_ledger(&ledger, &self.evidence, now()?)?;
        self.source.require_original_prefreeze_current()?;
        Ok(receipt)
    }

    pub(crate) fn into_original_material_parts(
        self, material: &OriginalCellQ24MaterialReceiptConfigV1,
    ) -> Result<(CircuitTaskSourceReadbackV1<FileAnchorWitnessStore>, AgentdIdentity,
        Arc<Mutex<LedgerWriter>>), Error>
    {
        let observed = self.read_original_publication()?;
        crate::cell_q24_dataset::require_source(&self.identity, &observed, &material.initial.request)
            .map_err(|_| Error::InvalidBinding)?;
        material.original_source_loan_binding(now()?).map_err(|_| Error::InvalidBinding)?;
        if material.verifier.trust_digest() != self.request.evidence_trust_digest
            || material.experience_signer != self.request.experience_signer
            || material.dataset_signer != self.request.dataset_signer
            || material.initial.owners.experience != self.request.experience_signer.principal.principal_id
            || material.initial.owners.dataset != self.request.dataset_signer.principal.principal_id
        { return Err(Error::InvalidBinding); }
        {
            let ledger = self.ledger.try_lock().map_err(|_| Error::Unavailable)?;
            self.request.require_ledger(&ledger, &self.evidence, now()?)?;
        }
        self.source.require_original_prefreeze_current()?;
        // No channel, counter, deadline, ledger or witness is rebuilt here.
        Ok((self.source, self.identity, self.ledger))
    }
}

//! Data for one supervisor-authorized disclosure of an already configured task.
//! Generator authentication is not Source-read authority. Only the protected
//! Root registration and that task's actual custody authorize the fixed read.
//! No future RunStart, Decision, publication digest or freeze is an input.

use codex_hepta_learning_ledger::{LearningEvidenceRoleV1, LearningEvidenceVerifierV1,
    LedgerWriter, SignedLearningEvidenceV1, TrustedLearningSignerV1};
use codex_hepta_types::{Digest32, StableId};
use crate::{AgentdRootAuthorityPeer, CircuitTaskSourceInputV1, CircuitTaskSourcePublicationV1};
use super::{Error, wire};
use super::super::super::codec;

/// Pre-existing task, ledger, trust and recipient facts. This value is data,
/// not a read grant. The host must independently authorize its exact contents
/// through the protected supervisor; a submitted signature cannot select them.
pub struct OriginalCircuitPrefreezeSourceRequestV1 {
    pub generation_operation_id: String,
    pub generation_intent_digest: Digest32,
    pub task_digest: Digest32,
    pub source: CircuitTaskSourceInputV1,
    pub ledger_binding_digest: Digest32,
    pub evidence_trust_digest: Digest32,
    pub trust_distribution_digest: Digest32,
    pub trust_generation: u64,
    pub generator: TrustedLearningSignerV1,
    pub experience_signer: TrustedLearningSignerV1,
    pub dataset_signer: TrustedLearningSignerV1,
    pub consumer: AgentdRootAuthorityPeer,
    pub consumer_uid: u32,
    pub nonce: [u8; 16],
}

impl OriginalCircuitPrefreezeSourceRequestV1 {
    /// Canonical challenge for the existing Generator's signature. This pure
    /// encoder does not sign, register a reader, create a RunStart or read Source.
    /// The fixed input exists before A; its actual RunStart first arrives through
    /// the authenticated Root read and is never reconstructed from a digest.
    pub fn signing_payload(&self) -> Result<Vec<u8>, Error> {
        StableId::new(&self.generation_operation_id).map_err(|_| Error::InvalidBinding)?;
        if self.generation_intent_digest.is_zero() || self.task_digest.is_zero()
            || self.ledger_binding_digest.is_zero() || self.evidence_trust_digest.is_zero()
            || self.trust_distribution_digest.is_zero() || self.trust_generation == 0
            || self.consumer_uid == 0 || self.consumer.pid == 0
            || self.consumer.pid > i32::MAX as u32 || self.consumer.process_start_ticks == 0
            || self.nonce == [0; 16] || self.source.observation.len() > wire::BOUND
            || self.source.candidates.len() > 64
            || !(1..=3_600_000).contains(&self.source.lease_duration_ms)
        { return Err(Error::InvalidBinding); }
        let mut out = wire::Writer::new(b"hepta.circuit.prefreeze-source-disclosure.v1\0");
        out.text(&self.generation_operation_id)?;
        for digest in [self.generation_intent_digest, self.task_digest,
            self.ledger_binding_digest, self.evidence_trust_digest, self.trust_distribution_digest]
        { out.digest(digest)?; }
        out.u64(self.trust_generation)?;
        // Match the original source configuration codec's fixed placeholder.
        // It is not an executed operation or a fabricated admission.
        let input = self.source.input(StableId::new("circuit-source")
            .map_err(|_| Error::InvalidBinding)?);
        out.bytes(&codec::encode_input(&input)?)?;
        out.u64(self.source.lease_duration_ms)?;
        for signer in [&self.generator, &self.experience_signer, &self.dataset_signer] {
            out.id(&signer.principal.principal_id)?;
            out.id(&signer.controller_id)?;
            out.raw(&signer.verifying_key)?;
        }
        out.text(&self.consumer.boot_id)?;
        out.u32(self.consumer.pid)?;
        out.u64(self.consumer.process_start_ticks)?;
        out.u32(self.consumer_uid)?;
        out.raw(&self.nonce)?;
        let payload = out.finish();
        wire::bounded(&payload)?;
        Ok(payload)
    }

    pub(crate) fn require_evidence(
        &self, verifier: &LearningEvidenceVerifierV1, distribution: Digest32,
        generation: u64, evidence: &SignedLearningEvidenceV1, at: u64,
    ) -> Result<Digest32, Error> {
        if verifier.trust_digest() != self.evidence_trust_digest
            || distribution != self.trust_distribution_digest || generation != self.trust_generation
            || verifier.objective_digest() != self.source.objective_digest
        { return Err(Error::InvalidBinding); }
        for (role, signer) in [
            (LearningEvidenceRoleV1::Generator, &self.generator),
            (LearningEvidenceRoleV1::Observer, &self.experience_signer),
            (LearningEvidenceRoleV1::Observer, &self.dataset_signer),
        ] {
            verifier.require_signer_binding(role, signer, at).map_err(|_| Error::InvalidBinding)?;
        }
        let payload = self.signing_payload()?;
        let actual = verifier.verify(LearningEvidenceRoleV1::Generator, evidence, &payload, at)
            .map_err(|_| Error::InvalidBinding)?;
        if actual.principal() != &self.generator.principal
            || actual.controller_id() != &self.generator.controller_id
        { return Err(Error::InvalidBinding); }
        Ok(Digest32::of_parts(&[
            b"hepta.circuit.prefreeze-source-connection.v1\0", &payload,
            &evidence.signing_bytes(), &evidence.signature,
        ]))
    }

    pub(crate) fn require_ledger(
        &self, ledger: &LedgerWriter, evidence: &SignedLearningEvidenceV1, at: u64,
    ) -> Result<Digest32, Error> {
        if ledger.binding_digest() != self.ledger_binding_digest {
            return Err(Error::InvalidBinding);
        }
        self.require_evidence(ledger.verifier(), ledger.trust_distribution_digest(),
            ledger.trust_generation(), evidence, at)
    }

    pub(crate) fn require_publication(&self, observed: &CircuitTaskSourcePublicationV1)
        -> Result<(), Error>
    {
        let record = observed.original_record();
        let expected = self.source.input(observed.input().operation_id.clone());
        if observed.input() != &expected || record.snapshot.run_id != self.source.scope.run_id
            || record.snapshot.objective_digest != self.source.objective_digest
        { return Err(Error::InvalidBinding); }
        Ok(())
    }
}

//! A narrow observer view of the original ordinary-task source. The original
//! writer remains inside its task driver/bootstrap; this handle cannot admit,
//! publish or withdraw a source and never caches a historical publication.

use codex_hepta_learning_ledger::RunStartRecordV1;
use codex_hepta_neuron::AnchorWitnessStore;
use codex_hepta_types::StableId;

use super::CircuitTaskSourcePublicationV1;
use super::DurableCircuitTaskSourceV1;
use super::Error;
use crate::AgentdIdentity;

#[cfg(target_os = "linux")]
#[path = "circuit_task_source_material.rs"]
pub(crate) mod material;

#[cfg(target_os = "linux")]
#[path = "circuit_task_source_prefreeze.rs"]
pub(crate) mod prefreeze;

enum OriginalReadback<W: AnchorWitnessStore> {
    Local(DurableCircuitTaskSourceV1<W>),
    #[cfg(target_os = "linux")]
    RootMaterial(std::sync::Arc<material::Client>),
    #[cfg(target_os = "linux")]
    RootPrefreeze(std::sync::Arc<prefreeze::Client>),
}

/// Only the original source owner constructs the local view. The sealed
/// Material branch consumes the real pair; the pre-freeze branch requires the
/// fixed supervisor disclosure and the actual Generator/ledger enrollment.
/// Every read reaches that same original locked journal, independent witness
/// and current withdrawal record, locally or through the sealed Material loan.
pub struct CircuitTaskSourceReadbackV1<W: AnchorWitnessStore> {
    original: OriginalReadback<W>,
}

impl<W: AnchorWitnessStore> Clone for CircuitTaskSourceReadbackV1<W> {
    fn clone(&self) -> Self {
        Self {
            original: match &self.original {
                OriginalReadback::Local(original) => OriginalReadback::Local(original.clone()),
                #[cfg(target_os = "linux")]
                OriginalReadback::RootMaterial(original) => OriginalReadback::RootMaterial(std::sync::Arc::clone(original)),
                #[cfg(target_os = "linux")]
                OriginalReadback::RootPrefreeze(original) => OriginalReadback::RootPrefreeze(std::sync::Arc::clone(original)),
            },
        }
    }
}

impl<W: AnchorWitnessStore> DurableCircuitTaskSourceV1<W> {
    /// Give an observer read access without either task-source writer trait.
    pub fn readback(&self) -> CircuitTaskSourceReadbackV1<W> {
        CircuitTaskSourceReadbackV1 {
            original: OriginalReadback::Local(self.clone()),
        }
    }
}

impl<W: AnchorWitnessStore> CircuitTaskSourceReadbackV1<W> {
    /// Check the original configured input without admitting a request or
    /// requiring a completed task. Selection can precede ordinary C execution.
    /// Both physical CURRENT reads retain the original lock and witness.
    pub(crate) fn require_original_input(
        &self,
        identity: &AgentdIdentity,
        input: &super::CircuitTaskSourceInputV1,
    ) -> Result<(), Error> {
        let original = match &self.original {
            OriginalReadback::Local(original) => original,
            #[cfg(target_os = "linux")]
            OriginalReadback::RootMaterial(_) => return Err(Error::InvalidBinding),
            #[cfg(target_os = "linux")]
            OriginalReadback::RootPrefreeze(_) => return Err(Error::InvalidBinding),
        };
        let mut owner = original.0.try_lock().map_err(|_| Error::Unavailable)?;
        owner.require_current()?;
        if identity != &owner.identity
            || owner.sources.get(input.scope.run_id.as_str()) != Some(input)
        {
            return Err(Error::InvalidBinding);
        }
        owner.require_active(input.scope.run_id.as_str())?;
        owner.require_current()
    }

    pub fn read_publication(
        &self,
        identity: &AgentdIdentity,
        record: &RunStartRecordV1,
    ) -> Result<CircuitTaskSourcePublicationV1, Error> {
        match &self.original {
            OriginalReadback::Local(original) => original.read_publication(identity, record),
            #[cfg(target_os = "linux")]
            OriginalReadback::RootMaterial(original) => {
                let observed = original.read(identity, &record.snapshot.run_id)?;
                if observed.original_record() != record { return Err(Error::InvalidBinding); }
                Ok(observed)
            }
            #[cfg(target_os = "linux")]
            OriginalReadback::RootPrefreeze(original) => {
                let observed = prefreeze::Client::read_prefreeze(original, identity, &record.snapshot.run_id)?;
                if observed.original_record() != record { return Err(Error::InvalidBinding); }
                Ok(observed)
            }
        }
    }

    pub fn read_run_publication(
        &self,
        identity: &AgentdIdentity,
        run_id: &StableId,
    ) -> Result<CircuitTaskSourcePublicationV1, Error> {
        match &self.original {
            OriginalReadback::Local(original) => original.read_run_publication(identity, run_id),
            #[cfg(target_os = "linux")]
            OriginalReadback::RootMaterial(original) => original.read(identity, run_id),
            #[cfg(target_os = "linux")]
            OriginalReadback::RootPrefreeze(original) => prefreeze::Client::read_prefreeze(original, identity, run_id),
        }
    }
}

